// After loading document, verify it belongs to the current user:
@PostAuthorize("returnObject.ownerUsername == authentication.name")
public Document getDocument(Long docId) {
    return documentRepo.findById(docId).orElseThrow();
    // Document is loaded from DB FIRST, then Spring checks the SpEL
}

// Return null if user doesn't own it:
@PostAuthorize("returnObject == null or returnObject.userId == authentication.principal.id")
public UserProfile getProfile(Long userId) { ... }
